const FIRESTORE_REQUEST_TIMEOUT_MS = 12_000;
function withFirestoreTimeout<T>(operation: Promise<T>, message: string) {
  let timeoutId: number | undefined;
  const timeout = new Promise<T>((_, reject) => {
    timeoutId = window.setTimeout(() => reject(new Error(message)), FIRESTORE_REQUEST_TIMEOUT_MS);
  });
  return Promise.race([operation, timeout]).finally(() => {
    if (timeoutId !== undefined) window.clearTimeout(timeoutId);
  });
}
