function getFirestoreErrorMessage(error: unknown) {
  const message = error instanceof Error ? error.message : String(error ?? "");
  if (message.includes("client is offline") || message.includes("Firestore tidak merespons") || message.includes("Cloud Firestore API")) return "Cloud Firestore belum aktif atau sedang tidak terjangkau. Aktifkan Cloud Firestore API pada project Firebase dat-baze, lalu muat ulang halaman.";
  return message || "Periksa koneksi internet dan konfigurasi Cloud Firestore, lalu coba lagi.";
}

