  useEffect(() => { if (!user || !db || !unlocked) { vaultHasLoadedRef.current = false; setVaultLoading(false); return; } let cancelled = false; setVaultLoading(true); (async () => { try { const snap = await getDocs(collection(db, `users/${user.uid}/accounts`)); const rows: VaultAccount[] = []; for (const item of snap.docs) { try { rows.push(await decryptAccount(item.data() as EncryptedRecord, master)); } catch { /* wrong key stays invisible */ } } if (!cancelled) setAccounts(rows); } catch (error) { if (!cancelled) toast.error("Data vault gagal dimuat", { description: error instanceof Error ? error.message : "Periksa koneksi dan coba lagi.", duration: getToastDuration() }); } finally { if (!cancelled) { vaultHasLoadedRef.current = true; setVaultLoading(false); } } })(); return () => { cancelled = true; }; }, [user, db, unlocked, master]);
